import json
import math
import sys
import time
from collections import Counter
from collections.abc import Mapping
from importlib.metadata import PackageNotFoundError, version

import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit.circuit import ParameterVector
from qiskit_aer import AerSimulator
from scipy.optimize import minimize


def _positive_integer(name, value):
    if isinstance(value, (bool, np.bool_)) or not isinstance(value, (int, np.integer)):
        raise ValueError(f"{name} must be a positive integer.")
    if value < 1:
        raise ValueError(f"{name} must be a positive integer.")
    return int(value)


def _canonical_state(state, n):
    """Identify complementary bit strings; researcher 0 belongs to division 0."""
    state = int(state)
    return state ^ ((1 << n) - 1) if state & 1 else state


def _partition_from_state(state, vertices):
    return {
        "division_0": [v for i, v in enumerate(vertices) if not ((state >> i) & 1)],
        "division_1": [v for i, v in enumerate(vertices) if (state >> i) & 1],
    }


def _reference_state(reference, vertices):
    """
    Accept None, two collections of researchers, researcher->division mappings,
    division->researcher-collection mappings, or a label vector in vertex order.
    The reference is evaluated only; it never seeds the solver.
    """
    if reference is None:
        return None

    vertex_set = set(vertices)
    n = len(vertices)
    groups = None
    labels = None

    if isinstance(reference, Mapping):
        if set(reference) == vertex_set:
            labels = [reference[v] for v in vertices]
        elif len(reference) == 2:
            groups = list(reference.values())
        else:
            raise ValueError("Invalid known_reference_partition mapping.")
    else:
        values = list(reference)
        if len(values) == 2 and all(
            isinstance(g, (list, tuple, set, frozenset, np.ndarray))
            for g in values
        ):
            groups = values
        elif len(values) == n:
            labels = values
        else:
            raise ValueError(
                "Reference must contain two groups or one division label per vertex."
            )

    if labels is not None:
        try:
            distinct_labels = list(dict.fromkeys(labels))
        except TypeError as exc:
            raise ValueError("Reference division labels must be hashable.") from exc
        if len(distinct_labels) != 2:
            raise ValueError("Reference must contain exactly two nonempty divisions.")
        groups = [
            {v for v, label in zip(vertices, labels) if label == distinct_labels[0]},
            {v for v, label in zip(vertices, labels) if label == distinct_labels[1]},
        ]

    try:
        group_0, group_1 = (set(g) for g in groups)
    except TypeError as exc:
        raise ValueError("Reference divisions must be collections of vertices.") from exc

    if (
        not group_0
        or not group_1
        or group_0 & group_1
        or group_0 | group_1 != vertex_set
    ):
        raise ValueError(
            "Reference divisions must be nonempty, disjoint, and cover all vertices."
        )

    state = sum(1 << i for i, v in enumerate(vertices) if v in group_1)
    return _canonical_state(state, n)


def _metrics(state, n, m, cuts, volumes):
    """
    Unweighted Newman-Girvan modularity and two-way normalized cut.

    Balance score = 1 - |division sizes difference| / n; higher is better.
    A zero-volume division contributes zero to normalized cut by convention.
    """
    state = int(state)
    cut = int(cuts[state])
    volume_1 = int(volumes[state])
    volume_0 = 2 * m - volume_1
    size_1 = state.bit_count()
    size_0 = n - size_1

    if m:
        modularity = (
            1.0
            - cut / m
            - (volume_0 / (2.0 * m)) ** 2
            - (volume_1 / (2.0 * m)) ** 2
        )
    else:
        modularity = 0.0

    normalized_cut = (
        (cut / volume_0 if volume_0 else 0.0)
        + (cut / volume_1 if volume_1 else 0.0)
    )
    return {
        "modularity_score": float(modularity),
        "normalized_cut_score": float(normalized_cut),
        "balance_constraint_score": float(1.0 - abs(size_0 - size_1) / n),
        "cut_edges": cut,
        "division_sizes": [size_0, size_1],
        "division_volumes": [volume_0, volume_1],
        "balance_constraint_satisfied": abs(size_0 - size_1) <= n % 2,
    }


def _approximation_ratio(cut, optimal_cut):
    """Conventional minimization ratio: achieved / optimum; 1 is optimal."""
    if optimal_cut:
        return float(cut / optimal_cut)
    return 1.0 if cut == 0 else float("inf")


def _repair_and_refine(counts, n, cuts, volumes, energies, max_candidates=16):
    """
    Hybrid decoding, without access to the exact optimum or reference partition.

    Repair sampled strings to equal (or near-equal) sizes, then descend through
    balanced swaps. Ties favor modularity via smaller volume imbalance, then
    the canonical state integer. Each accepted move strictly decreases this
    lexicographic key, so refinement terminates.
    """
    m_twice = int(volumes[-1])

    def rank(state):
        return (
            int(cuts[state]),
            abs(2 * int(volumes[state]) - m_twice),
            int(state),
        )

    def repair(state):
        while abs(n - 2 * state.bit_count()) > n % 2:
            majority_bit = int(2 * state.bit_count() > n)
            neighbors = [
                state ^ (1 << i)
                for i in range(n)
                if ((state >> i) & 1) == majority_bit
            ]
            state = min(neighbors, key=rank)
        return _canonical_state(state, n)

    raw_seeds = sorted(
        counts,
        key=lambda state: (float(energies[state]), -counts[state], state),
    )[:max_candidates]
    feasible_seeds = sorted(
        (
            state
            for state in counts
            if abs(n - 2 * state.bit_count()) <= n % 2
        ),
        key=lambda state: (rank(state), -counts[state]),
    )[:max_candidates]

    candidates = set(feasible_seeds)
    candidates.update(repair(state) for state in raw_seeds)
    candidates = sorted(candidates, key=rank)[:max_candidates]

    refined_states = []
    accepted_moves = 0
    for initial_state in candidates:
        state = initial_state
        while True:
            neighbors = set()
            for i in range(n):
                for j in range(i + 1, n):
                    if ((state >> i) & 1) != ((state >> j) & 1):
                        neighbors.add(
                            _canonical_state(state ^ (1 << i) ^ (1 << j), n)
                        )

            # For odd n, a majority-to-minority flip also preserves near-balance.
            if n % 2:
                majority_bit = int(2 * state.bit_count() > n)
                for i in range(n):
                    if ((state >> i) & 1) == majority_bit:
                        neighbors.add(_canonical_state(state ^ (1 << i), n))

            next_state = min(neighbors | {state}, key=rank)
            if rank(next_state) >= rank(state):
                break
            state = next_state
            accepted_moves += 1

        refined_states.append(state)

    return min(refined_states, key=rank), {
        "candidate_limit": max_candidates,
        "candidate_count": len(candidates),
        "accepted_local_moves": accepted_moves,
    }


def _software_versions():
    packages = {}
    for name in ("qiskit", "qiskit-aer", "numpy", "scipy"):
        try:
            packages[name] = version(name)
        except PackageNotFoundError:
            packages[name] = "unknown"
    return {"python": sys.version.split()[0], **packages}


def solve_graph_partition_qaoa(
    graph_vertices,
    graph_edges,
    known_reference_partition,
    p_layers=2,
    lambda_balance=1.0,
    lambda_cut=3.0,
    opt_shots=1024,
    final_shots=4096,
    maxiter=80,
    n_repro_runs=3,
    seed=42,
):
    """
    Execute sampled QAOA followed by balanced repair and local refinement.

    The primary optimization target is minimum cut subject to equal division
    sizes (sizes differ by at most one for odd n). For fixed division sizes,
    minimizing cross edges also maximizes aggregate within-division density.
    Modularity and normalized cut are reported as independent quality metrics,
    rather than incorrectly claimed to be the optimized objective.

    QAOA uses spins z_i in {-1,+1} and the soft-penalty Hamiltonian

        E(z) = lambda_cut * sum_edges (1 - z_i*z_j)/2
               + lambda_balance * (sum_i z_i)^2.

    Its ZZ coefficient is J_ij = 2*lambda_balance - lambda_cut*A_ij/2.
    A positive global Hamiltonian rescaling only rescales QAOA gamma angles.
    Hard balance is enforced during hybrid decoding even if the soft penalty
    is insufficient. The known reference never guides optimization.

    The approximation ratio is returned_cut / exact_minimum_balanced_cut:
    1 is optimal and larger values are worse. If the optimum is zero, the
    ratio is 1 for a zero returned cut and +infinity otherwise. Exhaustive
    benchmarking happens only after all quantum/hybrid runs have finished.

    This small-instance implementation uses 2**n classical energy tables and
    statevector simulation, and is limited to 20 vertices. Runtime is measured
    wall-clock seconds for the complete function, excluding module imports.
    """
    started = time.perf_counter()

    p_layers = _positive_integer("p_layers", p_layers)
    opt_shots = _positive_integer("opt_shots", opt_shots)
    final_shots = _positive_integer("final_shots", final_shots)
    maxiter = _positive_integer("maxiter", maxiter)
    n_repro_runs = _positive_integer("n_repro_runs", n_repro_runs)

    if isinstance(seed, (bool, np.bool_)) or not isinstance(seed, (int, np.integer)):
        raise ValueError("seed must be a nonnegative integer.")
    seed = int(seed)
    if seed < 0:
        raise ValueError("seed must be a nonnegative integer.")

    lambda_balance = float(lambda_balance)
    lambda_cut = float(lambda_cut)
    if not math.isfinite(lambda_balance) or lambda_balance < 0:
        raise ValueError("lambda_balance must be finite and nonnegative.")
    if not math.isfinite(lambda_cut) or lambda_cut <= 0:
        raise ValueError("lambda_cut must be finite and positive.")

    vertices = list(graph_vertices)
    n = len(vertices)
    if not 2 <= n <= 20:
        raise ValueError("This exact-benchmark workflow supports 2 through 20 vertices.")
    try:
        index = {v: i for i, v in enumerate(vertices)}
    except TypeError as exc:
        raise ValueError("Vertices must be hashable.") from exc
    if len(index) != n:
        raise ValueError("Vertices must be unique.")

    edges = []
    edge_set = set()
    degrees = np.zeros(n, dtype=np.int64)
    for edge in graph_edges:
        if len(edge) != 2:
            raise ValueError("Each edge must contain exactly two endpoints.")
        u, v = edge
        if u not in index or v not in index:
            raise ValueError(f"Unknown edge endpoint in {edge!r}.")
        i, j = sorted((index[u], index[v]))
        if i == j:
            raise ValueError("Self-loops are not supported.")
        if (i, j) in edge_set:
            raise ValueError(f"Duplicate undirected edge: {edge!r}.")
        edge_set.add((i, j))
        edges.append((i, j))
        degrees[i] += 1
        degrees[j] += 1
    edges.sort()
    m = len(edges)

    reference_state = _reference_state(known_reference_partition, vertices)

    # Qiskit integer bit i is qubit i, which represents vertices[i].
    states = np.arange(1 << n, dtype=np.uint64)
    bits = [((states >> i) & 1).astype(np.int8) for i in range(n)]
    populations = np.zeros(len(states), dtype=np.int16)
    volumes = np.zeros(len(states), dtype=np.int64)
    cuts = np.zeros(len(states), dtype=np.int64)

    for i in range(n):
        populations += bits[i]
        volumes += int(degrees[i]) * bits[i].astype(np.int64)
    for i, j in edges:
        cuts += bits[i] ^ bits[j]
    del bits

    imbalance = n - 2 * populations
    feasible = np.abs(imbalance) <= n % 2
    energies = (
        lambda_cut * cuts.astype(float)
        + lambda_balance * imbalance.astype(float) ** 2
    )
    if not np.all(np.isfinite(energies)):
        raise ValueError("Penalty weights overflow the energy representation.")

    couplings = []
    for i in range(n):
        for j in range(i + 1, n):
            coefficient = 2.0 * lambda_balance
            if (i, j) in edge_set:
                coefficient -= lambda_cut / 2.0
            if coefficient != 0.0:
                couplings.append((i, j, coefficient))

    hamiltonian_scale = max((abs(c) for _, _, c in couplings), default=1.0)
    constant_offset = lambda_cut * m / 2.0 + lambda_balance * n

    gamma = ParameterVector("gamma", p_layers)
    beta = ParameterVector("beta", p_layers)
    circuit = QuantumCircuit(n, n)
    circuit.h(range(n))
    for layer in range(p_layers):
        for i, j, coefficient in couplings:
            # RZZ(theta) = exp(-i * theta * Zi*Zj / 2).
            circuit.rzz(
                2.0 * gamma[layer] * coefficient / hamiltonian_scale, i, j
            )
        for i in range(n):
            circuit.rx(2.0 * beta[layer], i)
    circuit.measure(range(n), range(n))

    simulator = AerSimulator(
        method="statevector",
        device="CPU",
        max_parallel_threads=1,
        max_parallel_experiments=1,
    )

    def state_rank(state):
        return (
            int(cuts[state]),
            abs(2 * int(volumes[state]) - 2 * m),
            int(state),
        )

    run_records = []
    child_sequences = np.random.SeedSequence(seed).spawn(n_repro_runs)

    for run_index, child_sequence in enumerate(child_sequences):
        run_started = time.perf_counter()
        initialization_seed, transpiler_seed, optimization_seed, final_seed = [
            int(x) for x in child_sequence.generate_state(4, dtype=np.uint32)
        ]
        rng = np.random.default_rng(initialization_seed)
        compiled = transpile(
            circuit,
            simulator,
            optimization_level=1,
            seed_transpiler=transpiler_seed,
        )

        def sample(parameters, shots, simulator_seed):
            parameter_map = {
                gamma[layer]: float(parameters[layer])
                for layer in range(p_layers)
            }
            parameter_map.update(
                {
                    beta[layer]: float(parameters[p_layers + layer])
                    for layer in range(p_layers)
                }
            )
            bound = compiled.assign_parameters(
                parameter_map, inplace=False, strict=False
            )
            raw_counts = simulator.run(
                bound, shots=shots, seed_simulator=simulator_seed
            ).result().get_counts()

            # Complementary assignments have identical cost and metrics.
            canonical_counts = Counter()
            for bitstring, count in raw_counts.items():
                state = int(bitstring.replace(" ", ""), 2)
                canonical_counts[_canonical_state(state, n)] += int(count)
            return canonical_counts

        best_evaluation = {
            "value": float("inf"),
            "parameters": None,
            "mean_energy": None,
        }
        evaluations = 0

        def objective(parameters):
            nonlocal evaluations
            evaluations += 1
            counts = sample(parameters, opt_shots, optimization_seed)
            total = sum(counts.values())
            mean_energy = sum(
                float(energies[state]) * count for state, count in counts.items()
            ) / total
            value = (mean_energy - constant_offset) / hamiltonian_scale
            if value < best_evaluation["value"]:
                best_evaluation.update(
                    value=float(value),
                    parameters=np.array(parameters, dtype=float, copy=True),
                    mean_energy=float(mean_energy),
                )
            return float(value)

        initial_parameters = np.concatenate(
            (
                rng.uniform(0.0, np.pi, p_layers),
                rng.uniform(0.0, np.pi / 2.0, p_layers),
            )
        )
        optimization = minimize(
            objective,
            initial_parameters,
            method="COBYLA",
            options={"maxiter": maxiter, "rhobeg": 0.3, "tol": 1e-3},
        )

        # Fresh final sampling avoids reusing the optimization shot stream.
        final_counts = sample(
            best_evaluation["parameters"], final_shots, final_seed
        )
        total_final_shots = sum(final_counts.values())
        raw_best_state = min(
            final_counts,
            key=lambda state: (
                float(energies[state]),
                -final_counts[state],
                state,
            ),
        )
        feasible_samples = [state for state in final_counts if feasible[state]]
        best_feasible_sample = (
            min(feasible_samples, key=state_rank) if feasible_samples else None
        )

        decoded_state, refinement = _repair_and_refine(
            final_counts, n, cuts, volumes, energies
        )
        decoded_metrics = _metrics(decoded_state, n, m, cuts, volumes)

        record = {
            "run_index": run_index,
            "seeds": {
                "initialization": initialization_seed,
                "transpiler": transpiler_seed,
                "optimization_sampling": optimization_seed,
                "final_sampling": final_seed,
            },
            "partition": _partition_from_state(decoded_state, vertices),
            **decoded_metrics,
            "penalized_objective": float(energies[decoded_state]),
            "optimized_parameters": {
                "gamma": best_evaluation["parameters"][:p_layers].tolist(),
                "beta": best_evaluation["parameters"][p_layers:].tolist(),
            },
            "optimizer": {
                "method": "COBYLA",
                "function_evaluations": evaluations,
                "success": bool(optimization.success),
                "message": str(optimization.message),
                "best_sampled_mean_energy": best_evaluation["mean_energy"],
            },
            "final_sampled_mean_energy": float(
                sum(
                    float(energies[state]) * count
                    for state, count in final_counts.items()
                )
                / total_final_shots
            ),
            "final_sample_feasible_fraction": float(
                sum(final_counts[state] for state in feasible_samples)
                / total_final_shots
            ),
            "best_raw_sample": {
                "partition": _partition_from_state(raw_best_state, vertices),
                **_metrics(raw_best_state, n, m, cuts, volumes),
                "penalized_objective": float(energies[raw_best_state]),
            },
            "best_balanced_sample_cut": (
                int(cuts[best_feasible_sample])
                if best_feasible_sample is not None
                else None
            ),
            "classical_refinement": refinement,
            "compiled_circuit_depth": int(compiled.depth()),
            "compiled_gate_counts": {
                name: int(count) for name, count in compiled.count_ops().items()
            },
            "runtime_seconds": float(time.perf_counter() - run_started),
            "_state": decoded_state,
        }
        if reference_state is not None:
            record["matches_reference_up_to_swap"] = decoded_state == reference_state
            record["reference_sample_probability"] = float(
                final_counts.get(reference_state, 0) / total_final_shots
            )
        run_records.append(record)

    # Select the best hybrid result before computing the exhaustive benchmark.
    selected_record = min(run_records, key=lambda run: state_rank(run["_state"]))
    selected_state = selected_record["_state"]
    selected_metrics = _metrics(selected_state, n, m, cuts, volumes)

    benchmark_started = time.perf_counter()
    feasible_representatives = np.flatnonzero(feasible & ((states & 1) == 0))
    optimal_cut = int(cuts[feasible_representatives].min())
    optimal_candidates = feasible_representatives[
        cuts[feasible_representatives] == optimal_cut
    ]
    exact_state = int(min(optimal_candidates, key=state_rank))

    if m:
        balanced_cuts = cuts[feasible_representatives].astype(float)
        balanced_volume_1 = volumes[feasible_representatives].astype(float)
        balanced_volume_0 = 2.0 * m - balanced_volume_1
        modularities = (
            1.0
            - balanced_cuts / m
            - (balanced_volume_0 / (2.0 * m)) ** 2
            - (balanced_volume_1 / (2.0 * m)) ** 2
        )
        normalized_cuts = np.divide(
            balanced_cuts,
            balanced_volume_0,
            out=np.zeros_like(balanced_cuts),
            where=balanced_volume_0 > 0,
        ) + np.divide(
            balanced_cuts,
            balanced_volume_1,
            out=np.zeros_like(balanced_cuts),
            where=balanced_volume_1 > 0,
        )
        exact_max_modularity = float(modularities.max())
        exact_min_normalized_cut = float(normalized_cuts.min())
    else:
        exact_max_modularity = 0.0
        exact_min_normalized_cut = 0.0

    benchmark = {
        "method": "exhaustive balanced bipartitions modulo division exchange",
        "used_to_guide_solver": False,
        "partitions_evaluated": int(len(feasible_representatives)),
        "minimum_balanced_cut": optimal_cut,
        "maximum_balanced_modularity": exact_max_modularity,
        "minimum_balanced_normalized_cut": exact_min_normalized_cut,
        "optimal_cut_partition": _partition_from_state(exact_state, vertices),
        "optimal_cut_partition_metrics": _metrics(
            exact_state, n, m, cuts, volumes
        ),
        "runtime_seconds": float(time.perf_counter() - benchmark_started),
    }

    partition_frequencies = Counter(run["_state"] for run in run_records)
    for run in run_records:
        run["approximation_ratio"] = _approximation_ratio(
            run["cut_edges"], optimal_cut
        )
        run["cut_optimal"] = run["cut_edges"] == optimal_cut
        del run["_state"]

    statistics = {}
    for metric in (
        "modularity_score",
        "normalized_cut_score",
        "balance_constraint_score",
        "cut_edges",
    ):
        values = np.array([run[metric] for run in run_records], dtype=float)
        statistics[metric] = {
            "mean": float(values.mean()),
            "population_standard_deviation": float(values.std(ddof=0)),
            "minimum": float(values.min()),
            "maximum": float(values.max()),
        }

    reproducibility = {
        "master_seed": seed,
        "number_of_independent_restarts": n_repro_runs,
        "software_versions": _software_versions(),
        "backend": "qiskit_aer.AerSimulator",
        "simulation_method": "statevector with finite-shot measurement sampling",
        "simulator_threads": 1,
        "optimization_seed_policy": (
            "Fixed simulator seed within each run; independent initializations "
            "and fresh final-sampling seeds across runs."
        ),
        "same_seed_replay_tested": False,
        "repeatability_scope": (
            "Seeds, versions, and run parameters are recorded. Exact replay "
            "depends on the software/platform; wall-clock runtime is not reproducible."
        ),
        "all_restarts_same_partition": len(partition_frequencies) == 1,
        "most_common_partition_fraction": float(
            max(partition_frequencies.values()) / n_repro_runs
        ),
        "optimal_cut_fraction": float(
            sum(run["cut_optimal"] for run in run_records) / n_repro_runs
        ),
        "statistics": statistics,
        "runs": run_records,
    }
    if reference_state is not None:
        reproducibility["reference_match_fraction"] = float(
            sum(run["matches_reference_up_to_swap"] for run in run_records)
            / n_repro_runs
        )

    output = {
        "modularity_score": selected_metrics["modularity_score"],
        "normalized_cut_score": selected_metrics["normalized_cut_score"],
        "balance_constraint_score": selected_metrics["balance_constraint_score"],
        "approximation_ratio": _approximation_ratio(
            selected_metrics["cut_edges"], optimal_cut
        ),
        "runtime": None,
        "reproducibility": reproducibility,
        "partition": _partition_from_state(selected_state, vertices),
        "cut_edges": selected_metrics["cut_edges"],
        "division_sizes": selected_metrics["division_sizes"],
        "division_volumes": selected_metrics["division_volumes"],
        "balance_constraint_satisfied": selected_metrics[
            "balance_constraint_satisfied"
        ],
        "cross_division_edges": [
            [vertices[i], vertices[j]]
            for i, j in edges
            if ((selected_state >> i) & 1) != ((selected_state >> j) & 1)
        ],
        "selected_run_index": selected_record["run_index"],
        "selection_rule": (
            "Best hybrid restart by cut, then division-volume imbalance, "
            "then canonical bit-string integer."
        ),
        "graph": {"number_of_vertices": n, "number_of_edges": m},
        "configuration": {
            "p_layers": p_layers,
            "lambda_balance": lambda_balance,
            "lambda_cut": lambda_cut,
            "opt_shots": opt_shots,
            "final_shots": final_shots,
            "maxiter": maxiter,
            "hamiltonian_scale": float(hamiltonian_scale),
            "cost_function": (
                "lambda_cut * cut_edges + "
                "lambda_balance * (division_0_size - division_1_size)^2"
            ),
        },
        "metric_definitions": {
            "modularity_score": (
                "Newman-Girvan Q = sum_divisions "
                "[internal_edges/m - (division_volume/(2m))^2]; higher is better."
            ),
            "normalized_cut_score": (
                "cut/volume_0 + cut/volume_1; lower is better. "
                "A zero-volume term is defined as zero."
            ),
            "balance_constraint_score": (
                "1 - abs(size_0-size_1)/n; 1 denotes exactly equal sizes."
            ),
            "approximation_ratio": (
                "Returned cut / exact minimum balanced cut; 1 is optimal, "
